  "gowm-v0.6.2/semantic-attestation.schema.json": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "urn:gowm:v0.6.2:semantic-attestation",
    "title": "SemanticAttestation",
    "type": "object",
    "additionalProperties": false,
    "required": [
      "schemaVersion",
      "providerId",
      "operationId",
      "operationVersion",
      "semanticProfileHash",
      "rulesApplied",
      "evidence",
      "status"
    ],
    "properties": {
      "schemaVersion": {
        "const": "1.0"
      },
      "providerId": {
        "type": "string"
      },
      "operationId": {
        "type": "string"
      },
      "operationVersion": {
        "type": "string"
      },
      "semanticProfileHash": {
        "type": "string",
        "pattern": "^sha256:[0-9a-f]{64}$"
      },
      "rulesApplied": {
        "type": "array",
        "minItems": 1,
        "uniqueItems": true,
        "items": {
          "type": "string",
          "pattern": "^S[0-9]{3}$"
        }
      },
      "evidence": {
        "type": "array",
        "minItems": 1,
        "maxItems": 256,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "kind",
            "path",
            "sha256"
          ],
          "properties": {
            "kind": {
              "enum": [
                "DESCRIPTOR",
                "INPUT_SCHEMA",
                "OUTPUT_SCHEMA",
                "PORTS",
                "TYPESCRIPT_IMPLEMENTATION",
                "SQL_IMPLEMENTATION",
                "BRIDGE_CONTRACT",
                "SOURCE_LOCK",
                "UNIT_TEST",
                "BLACK_BOX_TEST",
                "ADR",
                "CALLER"
              ]
            },
            "path": {
              "type": "string",
              "minLength": 1,
              "maxLength": 1024
            },
            "symbol": {
              "type": "string",
              "maxLength": 256
            },
            "sha256": {
              "type": "string",
              "pattern": "^[0-9a-f]{64}$"
            }
          }
        }
      },
      "status": {
        "enum": [
          "PROVEN",
          "DOWNGRADED",
          "BLOCKED"
        ]
      },
      "notes": {
        "type": "array",
        "items": {
          "type": "string"
        }
      }
    }
  },
