          "inputSchemaHash": {
            "type": "string",
            "pattern": "^sha256:[0-9a-f]{64}$"
          },
          "outputSchemaHash": {
            "type": "string",
            "pattern": "^sha256:[0-9a-f]{64}$"
          },
          "semanticProfileHash": {
            "type": "string",
            "pattern": "^sha256:[0-9a-f]{64}$"
          },
